def paired(z,e):return z+'~'+e
def unit(anchor,m,b,formula,v,f,wrong,p):
 """Each input is a fully authored bilingual pair; boundaries are unit-specific."""
 def join(x,y):
  a,c=x.split('~');b,d=y.split('~');return paired(a+b,c+' '+d)
 az,ae=anchor.split('~')
 return dict(anchor=anchor,title=paired(az+'機理與驗證',ae+' mechanism and verification'),mechanism=join(m,b),
  model=join(paired('原創教學假設算例，以下量值用於簡化機理比較：','Original teaching example using hypothetical inputs to compare a simplified physical mechanism:'),formula),
  verify=v,failure=f,misconception=wrong,practice=p)

def institution(source_key):
 s=SOURCES[source_key]
 return dict(name=s['publisher'],nameEn=s['publisher'],business='水務管理、研究或工程技術資料提供機構',businessEn='Water management, research or engineering-information institution',url=s['url'],role='本課來源及技術參照機構；未宣稱承包任何列名工程',roleEn='Course source and technical reference; no contracting role in a named project is implied',investorUrl='',security=None)

def write(cid,focus,summary,units,example,keys,landmarks,place,nodes,history,timeline,codes,related=None):
 assert 261<=int(cid[1:])<=280 and len(units)==10
 t=TARGET[cid]
 facts=[]
 for u in units[:6]:
  z,e=u['model'].split('~');facts.append(paired(z,e))
 d=dict(id=cid,title=paired(t['title'],t['titleEn']),discipline=t['discipline'],family='water',focus=focus,summary=summary,units=units,example=example,
  history=history,timeline=timeline,codes=codes,landmarks=landmarks,place=place,
  sources=[{k:v for k,v in SOURCES[key].items() if k not in ('year','yearType','ref')} for key in keys],vendors=[institution(keys[0]),institution(keys[-1])],
  facts=facts,related=related or [f'b{261+(int(cid[1:])-260)%20}',f'b{261+(int(cid[1:])-259)%20}'],architectureNodes=nodes,architectureEdges=[[i,i+1] for i in range(len(nodes)-1)])
 (P/'inputs'/f'{cid}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 return d

