def research_log():
 path=P/'research_rivers.json'
 prior=json.loads(path.read_text()) if path.exists() else {}
 prior.update(reviewed='2026-10-21',author='courses_ground',sources=list(SOURCES.values()),
  limits=['All lesson numerical values are original hypothetical inputs, not field control settings or project measurements.','Guide/model references and owner case histories have separate scopes.','Supplier case statements are attributed; institutions are technical associations, not inferred contractors.','Dates describe verified publication or reported historical events, not unverified completion claims.'])
 prior['inputs']={f'b{i}':hashlib.sha256((P/'inputs'/f'b{i}.json').read_bytes()).hexdigest() for i in range(261,276) if (P/'inputs'/f'b{i}.json').exists()}
 path.write_text(json.dumps(prior,ensure_ascii=False,indent=2)+'\n')
